package com.dorm.fourchess;

import android.content.Context;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Independent per-player JSON files, atomic rename/backup, no passwords or tokens. */
final class PlayerArchive {
    private final File root;private final android.content.SharedPreferences prefs;
    PlayerArchive(Context c){root=new File(c.getFilesDir(),"players");if(!root.exists()&&!root.mkdirs())throw new IllegalStateException("无法创建档案目录");prefs=c.getSharedPreferences("career",0);}
    private File file(String id){if(!id.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("档案ID无效");return new File(root,id+".json");}
    synchronized JSONObject read(String id)throws Exception{AtomicFile f=new AtomicFile(file(id));try(InputStream in=f.openRead();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>=0){out.write(b,0,n);if(out.size()>2_000_000)throw new IOException("档案过大");}JSONObject d=new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));if(d.optInt("schema")!=1||!id.equals(d.optString("id")))throw new IOException("档案版本或ID不匹配");validate(d);return CareerRules.derive(d);}}
    synchronized void save(JSONObject d)throws Exception{validate(d);CareerRules.derive(d);CareerRules.put(d,"localRevision",d.optLong("localRevision")+1);CareerRules.put(d,"dirty",true);write(d);}
    synchronized void write(JSONObject d)throws Exception{validate(d);AtomicFile f=new AtomicFile(file(d.getString("id")));FileOutputStream stream=null;try{stream=f.startWrite();stream.write(d.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(stream);}catch(Exception e){if(stream!=null)f.failWrite(stream);throw e;}}
    private static String canonical(Object o)throws Exception{if(o instanceof JSONObject){JSONObject j=(JSONObject)o;ArrayList<String> names=new ArrayList<>();Iterator<String> it=j.keys();while(it.hasNext())names.add(it.next());Collections.sort(names);StringBuilder b=new StringBuilder("{");for(String n:names)b.append(JSONObject.quote(n)).append(':').append(canonical(j.get(n))).append(',');return b.append('}').toString();}if(o instanceof JSONArray){StringBuilder b=new StringBuilder("[");JSONArray a=(JSONArray)o;for(int i=0;i<a.length();i++)b.append(canonical(a.get(i))).append(',');return b.append(']').toString();}return String.valueOf(o);}
    static void validate(JSONObject d)throws Exception{if(d.optInt("schema")!=1||!d.optString("id").matches("[a-f0-9-]{36}"))throw new IOException("不支持的档案");if(d.toString().getBytes(StandardCharsets.UTF_8).length>750_000)throw new IOException("档案超过容量限制，请先导出备份");JSONObject p=d.optJSONObject("profile");if(p==null||p.optString("nickname").length()>24||p.optString("bio").length()>160)throw new IOException("档案字段无效");if(p.optInt("avatar",-1)<0||p.optInt("avatar",-1)>3)throw new IOException("头像编号无效");
        JSONObject outfit=d.optJSONObject("outfit");if(outfit!=null){String[] kinds={"frame","wall","card","title","board","piece","effect"},values={"plain|gold|jade|legend","night|hero0|hero1|hero2|hero3","night|jade","auto|hero0|hero1|hero2|hero3","ivory|jade","ivory|jade","quiet|ink"};for(int i=0;i<kinds.length;i++)if(!outfit.optString(kinds[i]).matches(values[i]))throw new IOException("装扮编号无效");}
        if(d.optJSONObject("matches")==null||d.optJSONObject("friends")==null||d.optJSONObject("outfit")==null)throw new IOException("档案结构不完整");}
    synchronized JSONObject create(String name,boolean guest)throws Exception{JSONObject d=new JSONObject(),p=new JSONObject(),outfit=new JSONObject();String id=UUID.randomUUID().toString();CareerRules.put(d,"schema",1);CareerRules.put(d,"id",id);CareerRules.put(d,"created",System.currentTimeMillis());CareerRules.put(d,"guest",guest);CareerRules.put(d,"profile",p);CareerRules.put(p,"nickname",clean(name,12,"棋友"));CareerRules.put(p,"bio","");CareerRules.put(p,"avatar",0);CareerRules.put(d,"matches",new JSONObject());CareerRules.put(d,"friends",new JSONObject());CareerRules.put(d,"badges",new JSONArray());CareerRules.put(d,"removedMatches",new JSONObject());CareerRules.put(d,"outfit",outfit);for(String v:new String[]{"frame:plain","wall:night","card:night","board:ivory","piece:ivory","effect:quiet","title:auto"}){String[] kv=v.split(":");CareerRules.put(outfit,kv[0],kv[1]);}save(d);select(id);return d;}
    static String clean(String value,int max,String fallback){String s=value==null?"":value.replaceAll("[\\p{Cntrl}]","").trim();return s.isEmpty()?fallback:s.substring(0,Math.min(max,s.length()));}
    synchronized ArrayList<JSONObject> list(){ArrayList<JSONObject> list=new ArrayList<>();File[] fs=root.listFiles((dir,n)->n.endsWith(".json"));if(fs!=null)for(File f:fs)try{list.add(read(f.getName().substring(0,36)));}catch(Exception ignored){}return list;}
    String selected(){return prefs.getString("selected","");}
    void select(String id){file(id);prefs.edit().putString("selected",id).apply();}
    JSONObject current()throws Exception{if(selected().isEmpty())return null;return read(selected());}
    synchronized void edit(String id,String nickname,String bio,int avatar)throws Exception{JSONObject d=read(id),p=d.getJSONObject("profile");CareerRules.put(p,"nickname",clean(nickname,12,"棋友"));CareerRules.put(p,"bio",clean(bio,160,""));CareerRules.put(p,"avatar",Math.max(0,Math.min(3,avatar)));save(d);}
    synchronized void equip(String id,String kind,String item)throws Exception{JSONObject d=read(id);if(!CareerRules.owns(d,kind+":"+item))throw new IOException("尚未解锁该装扮");CareerRules.put(d.getJSONObject("outfit"),kind,item);save(d);}
    synchronized void badges(String id,JSONArray ids)throws Exception{JSONObject d=read(id);if(ids.length()>3)throw new IOException("最多展示三个徽章");for(int i=0;i<ids.length();i++)if(!CareerRules.owns(d,"badge:"+ids.getString(i)))throw new IOException("成就尚未解锁");CareerRules.put(d,"badges",ids);save(d);}
    synchronized void addFriend(String owner,JSONObject card)throws Exception{JSONObject d=read(owner);String id=card.optString("id");if(!id.matches("[a-f0-9-]{36}")||id.equals(owner))throw new IOException("棋友ID无效或为自己");JSONObject friends=d.getJSONObject("friends");if(friends.has(id))throw new IOException("已经在棋友录中");JSONObject f=new JSONObject();CareerRules.put(f,"id",id);CareerRules.put(f,"nickname",clean(card.optString("nickname"),12,"棋友"));CareerRules.put(f,"avatar",Math.max(0,Math.min(3,card.optInt("avatar"))));CareerRules.put(f,"level",Math.max(1,Math.min(100,card.optInt("level",1))));CareerRules.put(f,"since",System.currentTimeMillis());CareerRules.put(f,"note","");CareerRules.put(f,"source","交换名片 · 身份未认证");CareerRules.put(friends,id,f);save(d);}
    synchronized void removeFriend(String owner,String id)throws Exception{JSONObject d=read(owner);d.getJSONObject("friends").remove(id);save(d);}
    synchronized void note(String owner,String friend,String value)throws Exception{JSONObject d=read(owner);JSONObject f=d.getJSONObject("friends").getJSONObject(friend);CareerRules.put(f,"note",clean(value,24,""));save(d);}
    static JSONObject card(JSONObject d){JSONObject c=new JSONObject(),p=CareerRules.object(d,"profile");CareerRules.put(c,"id",d.optString("id"));CareerRules.put(c,"nickname",p.optString("nickname"));CareerRules.put(c,"avatar",p.optInt("avatar"));CareerRules.put(c,"level",d.optInt("level",1));CareerRules.put(c,"title",CareerRules.title(d.optInt("level",1)));CareerRules.put(c,"version",1);return c;}
    synchronized boolean settle(String id,JSONObject match)throws Exception{JSONObject d=read(id);if(d.optBoolean("guest"))return false;JSONObject rows=d.getJSONObject("matches");String key=match.getString("id");if(rows.has(key))return false;CareerRules.put(rows,key,match);CareerRules.object(d,"removedMatches").remove(key);save(d);return true;}
    synchronized void retract(String id,String match)throws Exception{JSONObject d=read(id);if(d.getJSONObject("matches").has(match)){d.getJSONObject("matches").remove(match);JSONObject removed=CareerRules.object(d,"removedMatches");CareerRules.put(removed,match,System.currentTimeMillis());CareerRules.put(d,"removedMatches",removed);save(d);}}
    /** CAS conflict union preserves disjoint match IDs; conflicting edits require an explicit choice. */
    static JSONObject merge(JSONObject local,JSONObject remote,boolean localDetails)throws Exception{if(!local.getString("id").equals(remote.getString("id")))throw new IOException("不能合并不同账号");JSONObject result=CareerRules.copy(localDetails?local:remote),rows=CareerRules.copy(remote.getJSONObject("matches"));Iterator<String> keys=local.getJSONObject("matches").keys();while(keys.hasNext()){String k=keys.next();JSONObject m=local.getJSONObject("matches").getJSONObject(k);if(rows.has(k)&&!canonical(rows.getJSONObject(k)).equals(canonical(m)))throw new IOException("同一棋局记录冲突，请导出档案后人工处理");CareerRules.put(rows,k,m);}JSONObject removed=CareerRules.copy(CareerRules.object(remote,"removedMatches"));Iterator<String> removals=CareerRules.object(local,"removedMatches").keys();while(removals.hasNext()){String k=removals.next();CareerRules.put(removed,k,Math.max(removed.optLong(k),CareerRules.object(local,"removedMatches").optLong(k)));}Iterator<String> deleted=removed.keys();while(deleted.hasNext())rows.remove(deleted.next());CareerRules.put(result,"removedMatches",removed);CareerRules.put(result,"matches",rows);CareerRules.put(result,"cloudRevision",remote.optLong("cloudRevision"));return CareerRules.derive(result);}
}
